package cr.ac.cuc.nuevoavatar.persona5.notificacion;import java.time.OffsetDateTime;public record HistorialResponse(Long id,String destinatarios,String asunto,String htmlSanitizado,OffsetDateTime fecha,String usuario,String estado,String error){static HistorialResponse desde(Notificacion n){return new HistorialResponse(n.getId(),n.getDestinatarios(),n.getAsunto(),n.getHtmlSanitizado(),n.getFecha(),n.getUsuario(),n.getEstado(),n.getError());}}
